import { StrictMode, useEffect, useState } from 'react';
import { createRoot } from 'react-dom/client';
import './style.css';

type Capability = { provider: string; backend: string; status: string; operations: string[]; limitations: string[] };
type Grant = { provider: 'calendar' | 'reminders' | 'notes'; containerIds: string[]; actions: string[]; fields: 'full' | 'busy'; approval: 'automatic' | 'required'; expiresAt: number };
type Client = { id: string; name: string; revoked: boolean; policyVersion: number; grants: Grant[] };
type Operation = { id: string; provider: string; state: string; createdAt: number; expiresAt: number; clientId: string };
type OperationPreview = { id: string; clientId: string; provider: string; state: string; expiresAt: number; change: unknown };
type OperationPage = { items: Operation[]; total: number; offset: number; limit: number };
type Audit = { at: number; provider?: string; action: string; outcome: string; count: number; clientId?: string; errorCode?: string };
type AuditSummary = { count: number; bytes: number };
type Page<T> = { items: T[]; total: number; offset: number; limit: number };
type Bootstrap = { csrf: string; capabilities: Capability[] };
type Diagnostics = { version: string; nativeProtocolVersion: number; systemPermissions: string; audit: AuditSummary; storage: { operationsByState: Record<string, number>; pageSize: number; pageCount: number; freePages: number; recentErrors: Array<{ at: number; provider?: string; action: string; errorCode?: string }> } };
type ReminderDiagnostic = { probeId: string; containerId: string; createdAt: number; updatedAt: number; recoveryStatus: string; active: boolean; events: Array<{ stage: string; status: string; at: number; durationMs?: number }> };
type ContainerDiscovery = { query: string; reminderLists: Array<{ id: string; name: string }>; noteFolders: Array<{ id: string; name: string; shared: boolean | null }>; personalDataRead: false };
type Reminder = { id: string; listId: string; title: string; body: string; completed: boolean; due: string | null };
type ReminderPage = { items: Reminder[]; nextOffset: number | null };
type Calendar = { id: string; name: string };
type CalendarEvent = { id: string; calendarId: string; title: string; start: string; end: string; allDay: boolean; location: string; notes: string };
type CalendarPage = { calendar: Calendar; items: CalendarEvent[]; nextOffset: number | null };
type PermissionStatus = { calendar: string; reminders: string };
type WebWriteResult = { id: string; provider: 'reminders' | 'calendar'; state: 'executing' | 'succeeded' | 'failed' | 'outcome_unknown'; result: { id: string; containerId: string } | null };

async function api<T>(csrf: string, method: string, params: Record<string, unknown> = {}): Promise<T> {
  const response = await fetch('/api/rpc', { method: 'POST', credentials: 'same-origin', headers: { 'content-type': 'application/json', 'x-csrf-token': csrf }, body: JSON.stringify({ method, params }) });
  const payload = await response.json() as { ok: boolean; result?: T; error?: { message: string } };
  if (!payload.ok) throw new Error(payload.error?.message ?? 'Management request failed.');
  return payload.result as T;
}
function date(value: number): string { return new Date(value).toLocaleString(); }
function dateInputValue(value: Date): string { return `${value.getFullYear()}-${String(value.getMonth() + 1).padStart(2, '0')}-${String(value.getDate()).padStart(2, '0')}`; }
function currentMonthRange(): { from: string; to: string } { const now = new Date(); return { from: dateInputValue(new Date(now.getFullYear(), now.getMonth(), 1)), to: dateInputValue(new Date(now.getFullYear(), now.getMonth() + 1, 0)) }; }
function rangeStart(value: string): string { return new Date(`${value}T00:00:00`).toISOString(); }
function rangeEnd(value: string): string { const end = new Date(`${value}T00:00:00`); end.setDate(end.getDate() + 1); return end.toISOString(); }
function localDateTime(value: string): string { const date = new Date(value); const pad = (n: number) => String(n).padStart(2, '0'); return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}`; }
function dateTimeIso(value: string): string { return new Date(value).toISOString(); }

type WebAudit = Audit & { source?: 'client' | 'web'; target?: string; operationId?: string; durationMs?: number };
function WebApps({ csrf, report }: { csrf: string; report: (message: string) => void }) {
  const [app, setApp] = useState<'calendar' | 'reminders'>('calendar');
  const [calendar, setCalendar] = useState(''); const [calendarRange] = useState(currentMonthRange); const [from, setFrom] = useState(calendarRange.from); const [to, setTo] = useState(calendarRange.to);
  const [calendarResult, setCalendarResult] = useState<CalendarPage>(); const [resolvedCalendar, setResolvedCalendar] = useState<Calendar>(); const [calendarOffset, setCalendarOffset] = useState(0);
  const [calendarPermission, setCalendarPermission] = useState<PermissionStatus>();
  const [calendarEditing, setCalendarEditing] = useState<CalendarEvent>(); const [calendarTitle, setCalendarTitle] = useState(''); const [calendarStart, setCalendarStart] = useState(''); const [calendarEnd, setCalendarEnd] = useState(''); const [calendarAllDay, setCalendarAllDay] = useState(false); const [calendarLocation, setCalendarLocation] = useState(''); const [calendarNotes, setCalendarNotes] = useState(''); const [calendarMessage, setCalendarMessage] = useState('');
  const [container, setContainer] = useState(''); const [offset, setOffset] = useState(0); const [discovery, setDiscovery] = useState<ContainerDiscovery>(); const [resolvedList, setResolvedList] = useState<{ id: string; name: string }>();
  const [title, setTitle] = useState(''); const [body, setBody] = useState(''); const [dueDate, setDueDate] = useState(''); const [result, setResult] = useState<unknown>(); const [busy, setBusy] = useState(false); const [pendingId, setPendingId] = useState(() => localStorage.getItem('ac_web_operation_id') ?? '');
  const [editing, setEditing] = useState<Reminder>(); const [mutationMessage, setMutationMessage] = useState('');
  const requestCalendarPermission = async () => { setBusy(true); try { setCalendarPermission(await api<PermissionStatus>(csrf, 'diagnostics.permissions.request', { provider: 'calendar' })); } catch (error) { report(error instanceof Error ? error.message : '无法请求日历访问权限。'); } finally { setBusy(false); } };
  const loadCalendar = async (target: Calendar, nextOffset = 0) => { setBusy(true); try { const page = await api<CalendarPage>(csrf, 'web.calendar.list_events', { calendarId: target.id, from: rangeStart(from), to: rangeEnd(to), offset: nextOffset, limit: 50 }); setResolvedCalendar(page.calendar); setCalendarResult(page); setCalendarOffset(nextOffset); } catch (error) { report(error instanceof Error ? error.message : '无法读取日程。'); } finally { setBusy(false); } };
  const resetCalendarForm = () => { setCalendarEditing(undefined); setCalendarTitle(''); setCalendarStart(''); setCalendarEnd(''); setCalendarAllDay(false); setCalendarLocation(''); setCalendarNotes(''); };
  const editCalendar = (item: CalendarEvent) => { setCalendarEditing(item); setCalendarTitle(item.title); setCalendarStart(localDateTime(item.start)); setCalendarEnd(localDateTime(item.end)); setCalendarAllDay(item.allDay); setCalendarLocation(item.location); setCalendarNotes(item.notes); };
  const submitCalendar = async (event: React.FormEvent) => { event.preventDefault(); if (!resolvedCalendar) return; if (Date.parse(calendarEnd) <= Date.parse(calendarStart)) { report('结束时间必须晚于开始时间。'); return; } const key = crypto.randomUUID(); setBusy(true); setCalendarMessage(''); try { const change = { kind: calendarEditing ? 'calendar.update' : 'calendar.create', containerId: resolvedCalendar.id, ...(calendarEditing ? { id: calendarEditing.id } : {}), title: calendarTitle, start: dateTimeIso(calendarStart), end: dateTimeIso(calendarEnd), allDay: calendarAllDay, location: calendarLocation, notes: calendarNotes }; const operation = await api<WebWriteResult>(csrf, calendarEditing ? 'web.calendar.update' : 'web.calendar.create', { idempotencyKey: key, change }); if (operation.state !== 'succeeded') throw new Error(operation.state === 'outcome_unknown' ? '操作结果未知，请到日历 App 核验；系统不会自动重试。' : '操作未成功。'); setCalendarMessage(calendarEditing ? '日程已保存。' : '日程已新建。'); resetCalendarForm(); await loadCalendar(resolvedCalendar, calendarOffset); } catch (error) { report(error instanceof Error ? error.message : '无法保存日程。'); } finally { setBusy(false); } };
  const deleteCalendar = async (item: CalendarEvent) => { if (!resolvedCalendar || !window.confirm(`删除“${item.title}”？此操作不可撤销。`)) return; const key = crypto.randomUUID(); setBusy(true); setCalendarMessage(''); try { const operation = await api<WebWriteResult>(csrf, 'web.calendar.delete', { idempotencyKey: key, change: { kind: 'calendar.delete', containerId: resolvedCalendar.id, id: item.id } }); if (operation.state !== 'succeeded') throw new Error(operation.state === 'outcome_unknown' ? '操作结果未知，请到日历 App 核验；系统不会自动重试。' : '操作未成功。'); setCalendarMessage('日程已删除。'); await loadCalendar(resolvedCalendar, calendarOffset); } catch (error) { report(error instanceof Error ? error.message : '无法删除日程。'); } finally { setBusy(false); } };
  const loadReminders = async (list: { id: string; name: string }, nextOffset = 0) => { setBusy(true); try { setOffset(nextOffset); setResult(await api<ReminderPage>(csrf, 'web.reminders.list', { listId: list.id, offset: nextOffset, limit: 50 })); } catch (error) { report(error instanceof Error ? error.message : '无法读取提醒事项。'); } finally { setBusy(false); } };
  const resolveAndLoad = async () => { const name = container.trim(); if (!name) return; setBusy(true); try { const found = await api<ContainerDiscovery>(csrf, 'web.find_containers', { name }); setDiscovery(found); if (found.reminderLists.length !== 1) throw new Error(found.reminderLists.length ? '找到多个同名清单；请先在提醒事项 App 中改为唯一名称。' : '没有找到该精确名称的清单。'); const list = found.reminderLists[0]!; setResolvedList(list); await loadReminders(list); } catch (error) { report(error instanceof Error ? error.message : '无法解析清单名称。'); setBusy(false); } };
  const create = async () => {
    if (!resolvedList) return; const key = crypto.randomUUID(); setPendingId(key); localStorage.setItem('ac_web_operation_id', key); const change = { kind: 'reminders.create', containerId: resolvedList.id, title, body, ...(dueDate ? { due: { kind: 'date', date: dueDate } } : {}) };
    await run('web.reminders.create', { idempotencyKey: key, change });
  };
  const mutate = async (method: 'web.reminders.update' | 'web.reminders.delete', change: Record<string, unknown>, successMessage: string) => { const key = crypto.randomUUID(); setPendingId(key); localStorage.setItem('ac_web_operation_id', key); setBusy(true); setMutationMessage(''); try { const operation = await api<WebWriteResult>(csrf, method, { idempotencyKey: key, change }); if (operation.state !== 'succeeded') { if (operation.state === 'outcome_unknown') throw new Error('操作结果未知，请到提醒事项 App 核验；系统不会自动重试。'); throw new Error('操作未成功，请重试。'); } setMutationMessage(successMessage); return true; } catch (error) { report(error instanceof Error ? error.message : '操作失败。'); return false; } finally { setBusy(false); } };
  const update = async () => { if (!editing || !resolvedList) return; const ok = await mutate('web.reminders.update', { kind: 'reminders.update', containerId: resolvedList.id, id: editing.id, title: editing.title, body: editing.body, completed: editing.completed }, '提醒事项已保存。'); if (ok) { setEditing(undefined); await loadReminders(resolvedList, offset); } };
  const complete = async (item: Reminder) => { if (!resolvedList || item.completed) return; const ok = await mutate('web.reminders.update', { kind: 'reminders.update', containerId: resolvedList.id, id: item.id, title: item.title, body: item.body, completed: true }, `“${item.title}”已完成。`); if (ok) await loadReminders(resolvedList, offset); };
  const remove = async (item: Reminder) => { if (!resolvedList || !window.confirm(`删除“${item.title}”？此操作不可撤销。`)) return; const ok = await mutate('web.reminders.delete', { kind: 'reminders.delete', containerId: resolvedList.id, id: item.id }, `“${item.title}”已删除。`); if (ok) await loadReminders(resolvedList, offset); };
  const recover = async () => { if (!pendingId) return; await run('web.operations.get', { id: pendingId }); };
  const nextOffset = result && typeof result === 'object' && 'nextOffset' in result && typeof (result as { nextOffset?: unknown }).nextOffset === 'number' ? (result as { nextOffset: number }).nextOffset : null;
  return <section><h2>APPs</h2><nav className="subnav">{([['calendar', '日历'], ['reminders', '提醒事项']] as const).map(([key, label]) => <button key={key} className={app === key ? 'active' : ''} onClick={() => { setApp(key); setResult(undefined); setOffset(0); }}>{label}</button>)}</nav>
    {app === 'calendar' && <div className="calendar-layout"><div><form onSubmit={(e) => { e.preventDefault(); setCalendarResult(undefined); setResolvedCalendar(undefined); resetCalendarForm(); void loadCalendar({ id: calendar.trim(), name: calendar.trim() }); }}><p>按日历精确名称和日期范围查询日程事件；不存在或重名的日历会被拒绝。</p><p className="permission-help">首次使用需要授予此 Helper“日历完全访问”权限。<button type="button" disabled={busy} onClick={() => void requestCalendarPermission()}>授予日历访问权限</button>{calendarPermission && <small>当前日历权限：{calendarPermission.calendar}</small>}</p><label>日历名称<input required value={calendar} onChange={(e) => setCalendar(e.target.value)} /></label><label>开始日期<input required type="date" value={from} onChange={(e) => setFrom(e.target.value)} /></label><label>结束日期<input required type="date" min={from} value={to} onChange={(e) => setTo(e.target.value)} /></label><button disabled={busy} type="submit">查询日程</button></form>{resolvedCalendar && <form onSubmit={submitCalendar}><h3>{calendarEditing ? '编辑日程' : '新建日程'}</h3><label>标题<input required value={calendarTitle} onChange={(e) => setCalendarTitle(e.target.value)} /></label><label>开始时间<input required type="datetime-local" value={calendarStart} onChange={(e) => setCalendarStart(e.target.value)} /></label><label>结束时间<input required type="datetime-local" value={calendarEnd} onChange={(e) => setCalendarEnd(e.target.value)} /></label><label className="check"><input type="checkbox" checked={calendarAllDay} onChange={(e) => setCalendarAllDay(e.target.checked)} />全天</label><label>地点<input value={calendarLocation} onChange={(e) => setCalendarLocation(e.target.value)} /></label><label>备注<textarea value={calendarNotes} onChange={(e) => setCalendarNotes(e.target.value)} /></label><button disabled={busy || !calendarTitle.trim()} type="submit">{calendarEditing ? '保存' : '新建'}</button>{calendarEditing && <button type="button" disabled={busy} onClick={resetCalendarForm}>取消</button>}</form>}</div><div className="calendar-results"><h3>日程</h3>{resolvedCalendar && <p className="resolved-list">已选择：<strong>{resolvedCalendar.name}</strong><span>日历 ID：<code>{resolvedCalendar.id}</code></span></p>}{calendarMessage && <p className="success-message">{calendarMessage}</p>}{calendarResult ? <>{calendarResult.items.length ? <div className="calendar-list">{calendarResult.items.map((item) => <article className="calendar-card" key={item.id}><h4>{item.title || '无标题日程'}</h4><p>{item.allDay ? '全天' : `${new Date(item.start).toLocaleString()} 至 ${new Date(item.end).toLocaleString()}`}</p>{item.location && <small>地点：{item.location}</small>}{item.notes && <small>备注：{item.notes}</small>}<div className="card-actions"><button type="button" disabled={busy} onClick={() => editCalendar(item)}>编辑</button><button type="button" className="danger" disabled={busy} onClick={() => void deleteCalendar(item)}>删除</button></div></article>)}</div> : <p className="empty">该时间范围内没有日程。</p>}<p className="pagination"><button type="button" disabled={busy || calendarOffset === 0} onClick={() => resolvedCalendar && void loadCalendar(resolvedCalendar, Math.max(0, calendarOffset - 50))}>上一页</button><button type="button" disabled={busy || calendarResult.nextOffset === null} onClick={() => resolvedCalendar && calendarResult.nextOffset !== null && void loadCalendar(resolvedCalendar, calendarResult.nextOffset)}>下一页</button></p></> : <p className="empty">查询后将在这里显示日程。</p>}</div></div>}
    {app === 'reminders' && <div className="reminders-layout"><div><form onSubmit={(e) => { e.preventDefault(); void resolveAndLoad(); }}><p>输入清单的精确名称即可；页面会自动解析唯一 ID。结果未知时请到提醒事项 App 核验，切勿自动重试。</p><label>清单名称<input required value={container} onChange={(e) => { setContainer(e.target.value); setResolvedList(undefined); }} placeholder="例如：工作" /></label><button disabled={busy} type="submit">查询提醒事项</button></form>{resolvedList && <p className="resolved-list">已选择：<strong>{resolvedList.name}</strong><span>清单 ID：<code>{resolvedList.id}</code></span></p>}<form onSubmit={(e) => { e.preventDefault(); void create(); }}><h3>新增提醒事项</h3><label>标题<input required value={title} onChange={(e) => setTitle(e.target.value)} /></label><label>备注<textarea value={body} onChange={(e) => setBody(e.target.value)} /></label><label>到期日期（可选）<input type="date" value={dueDate} onChange={(e) => setDueDate(e.target.value)} /></label><button disabled={busy || !resolvedList} type="submit">新增</button></form></div><div className="reminder-results"><h3>提醒事项</h3>{mutationMessage && <p className="success-message">{mutationMessage}</p>}{result && typeof result === 'object' && 'items' in result ? <>{(result as ReminderPage).items.length ? <div className="reminder-list">{(result as ReminderPage).items.map((item) => <article className="reminder-card" key={item.id}><div><h4>{item.title}</h4><p>{item.body || '无备注'}</p><small>{item.completed ? '已完成' : '未完成'} · {item.due ? `到期：${new Date(item.due).toLocaleString()}` : '无到期日'}</small></div><div className="card-actions"><button type="button" className="complete" disabled={busy || item.completed} onClick={() => void complete(item)}>{item.completed ? '已完成' : '完成'}</button><button type="button" disabled={busy} onClick={() => setEditing({ ...item })}>编辑</button><button type="button" className="danger" disabled={busy} onClick={() => void remove(item)}>删除</button></div></article>)}</div> : <p className="empty">这个清单里还没有提醒事项。</p>}<p className="pagination"><button type="button" disabled={busy || offset === 0} onClick={() => resolvedList && void loadReminders(resolvedList, Math.max(0, offset - 50))}>上一页</button><button type="button" disabled={busy || (result as ReminderPage).nextOffset === null} onClick={() => { const next = (result as ReminderPage).nextOffset; if (resolvedList && next !== null) void loadReminders(resolvedList, next); }}>下一页</button></p></> : <p className="empty">查询后将在这里显示提醒事项。</p>}</div>{editing && <div className="edit-panel"><h3>编辑提醒事项</h3><label>标题<input value={editing.title} onChange={(e) => setEditing({ ...editing, title: e.target.value })} /></label><label>备注<textarea value={editing.body} onChange={(e) => setEditing({ ...editing, body: e.target.value })} /></label><label className="check"><input type="checkbox" checked={editing.completed} onChange={(e) => setEditing({ ...editing, completed: e.target.checked })} />标记为已完成</label><p><button type="button" disabled={busy || !editing.title.trim()} onClick={() => void update()}>保存</button> <button type="button" disabled={busy} onClick={() => setEditing(undefined)}>取消</button></p></div>}</div>}
    {app !== 'reminders' && (result !== undefined || pendingId) && <article className="result"><h3>结果</h3>{pendingId && <p>最近写入操作编号：<code>{pendingId}</code> <button disabled={busy} onClick={() => void recover()}>恢复状态</button></p>}{result !== undefined && <pre><code>{JSON.stringify(result, null, 2)}</code></pre>}{app === 'calendar' && result !== undefined && <p><button disabled={busy || offset === 0} onClick={() => { const next = Math.max(0, offset - 50); setOffset(next); void run('web.calendar.list_events', { calendarId: calendar, from: new Date(from).toISOString(), to: new Date(to).toISOString(), offset: next, limit: 50 }); }}>上一页</button> <button disabled={busy || nextOffset === null} onClick={() => { if (nextOffset === null) return; setOffset(nextOffset); void run('web.calendar.list_events', { calendarId: calendar, from: new Date(from).toISOString(), to: new Date(to).toISOString(), offset: nextOffset, limit: 50 }); }}>下一页</button> 当前偏移：{offset}{nextOffset === null ? '（没有更多结果）' : ''}</p>}</article>}
  </section>;
}

function WebAuditPage({ csrf, report }: { csrf: string; report: (message: string) => void }) {
  const [items, setItems] = useState<WebAudit[]>([]); const [provider, setProvider] = useState(''); const [outcome, setOutcome] = useState(''); const [from, setFrom] = useState(''); const [to, setTo] = useState(''); const [offset, setOffset] = useState(0); const [total, setTotal] = useState(0);
  const load = async (nextOffset = offset) => { try { const page = await api<Page<WebAudit>>(csrf, 'audit.query', { source: 'web', offset: nextOffset, limit: 50, ...(provider ? { provider } : {}), ...(outcome ? { outcome } : {}), ...(from ? { from: Date.parse(from) } : {}), ...(to ? { to: Date.parse(to) } : {}) }); setItems(page.items); setOffset(page.offset); setTotal(page.total); } catch (error) { report(error instanceof Error ? error.message : '无法读取审计。'); } };
  useEffect(() => { void load(); }, []);
  return <section><h2>审计</h2><p>仅显示 Web 调试操作；不会保存笔记正文、提醒备注或完整事件内容。</p><p><label>App<select value={provider} onChange={(e) => setProvider(e.target.value)}><option value="">全部</option><option value="calendar">日历</option><option value="reminders">提醒事项</option><option value="notes">备忘录</option></select></label><label>结果<select value={outcome} onChange={(e) => setOutcome(e.target.value)}><option value="">全部</option><option value="succeeded">成功</option><option value="failed">失败</option><option value="outcome_unknown">结果未知</option></select></label><label>开始<input type="datetime-local" value={from} onChange={(e) => setFrom(e.target.value)} /></label><label>结束<input type="datetime-local" value={to} onChange={(e) => setTo(e.target.value)} /></label><button onClick={() => void load(0)}>刷新</button></p><p><button disabled={offset === 0} onClick={() => void load(Math.max(0, offset - 50))}>上一页</button> <button disabled={offset + items.length >= total} onClick={() => void load(offset + 50)}>下一页</button> 显示 {total ? offset + 1 : 0}–{offset + items.length} / {total}</p><table><thead><tr><th>时间</th><th>App / 动作</th><th>结果</th><th>耗时</th><th>目标</th><th>操作编号</th></tr></thead><tbody>{items.map((item, index) => <tr key={`${item.at}-${index}`}><td>{date(item.at)}</td><td>{item.provider ?? '系统'} / {item.action}</td><td>{item.outcome}</td><td>{item.durationMs === undefined ? '—' : `${item.durationMs} ms`}</td><td>{item.target ?? '—'}</td><td>{item.operationId ?? '—'}</td></tr>)}</tbody></table></section>;
}

function App() {
  const [bootstrap, setBootstrap] = useState<Bootstrap>();
  const [page, setPage] = useState<'apps' | 'audit' | 'connections' | 'sources' | 'records' | 'pending' | 'diagnostics' | 'mcp'>('apps');
  const [clients, setClients] = useState<Client[]>([]);
  const [operations, setOperations] = useState<Operation[]>([]);
  const [operationRows, setOperationRows] = useState<Operation[]>([]);
  const [operationTotal, setOperationTotal] = useState(0);
  const [operationOffset, setOperationOffset] = useState(0);
  const [operationProvider, setOperationProvider] = useState('');
  const [operationState, setOperationState] = useState('');
  const [preview, setPreview] = useState<OperationPreview>();
  const [audit, setAudit] = useState<Audit[]>([]);
  const [auditTotal, setAuditTotal] = useState(0);
  const [auditOffset, setAuditOffset] = useState(0);
  const [auditProvider, setAuditProvider] = useState('');
  const [auditOutcome, setAuditOutcome] = useState('');
  const [auditClientId, setAuditClientId] = useState('');
  const [auditFrom, setAuditFrom] = useState('');
  const [auditTo, setAuditTo] = useState('');
  const [auditSummary, setAuditSummary] = useState<AuditSummary>({ count: 0, bytes: 0 });
  const [diagnostics, setDiagnostics] = useState<Diagnostics>();
  const [reminderDiagnostics, setReminderDiagnostics] = useState<ReminderDiagnostic[]>([]);
  const [diagnosticListId, setDiagnosticListId] = useState('');
  const [probeResult, setProbeResult] = useState<unknown>();
  const [debugClientId, setDebugClientId] = useState('');
  const [debugProvider, setDebugProvider] = useState<'reminders' | 'notes'>('reminders');
  const [debugContainerId, setDebugContainerId] = useState('');
  const [debugReadResult, setDebugReadResult] = useState<unknown>();
  const [error, setError] = useState('');
  const [createdToken, setCreatedToken] = useState('');
  const [editingClient, setEditingClient] = useState<Client>();
  const [editingGrantIndex, setEditingGrantIndex] = useState(0);
  const [name, setName] = useState('');
  const [provider, setProvider] = useState<'calendar' | 'reminders' | 'notes'>('reminders');
  const [containerIds, setContainerIds] = useState('');
  const [containerName, setContainerName] = useState('');
  const [containerDiscovery, setContainerDiscovery] = useState<ContainerDiscovery>();
  const [actions, setActions] = useState<string[]>(['read']);
  const [fields, setFields] = useState<'full' | 'busy'>('full');
  const [approval, setApproval] = useState<'automatic' | 'required'>('automatic');
  const [expiresAt, setExpiresAt] = useState(() => new Date(Date.now() + 30 * 24 * 60 * 60_000).toISOString().slice(0, 16));
  const mcpConfig = createdToken ? JSON.stringify({ mcpServers: { 'apple-connector': { command: 'apple-connector', args: ['mcp'], env: { APPLE_CONNECTOR_TOKEN: createdToken } } } }, null, 2) : '';
  const refresh = async (csrf = bootstrap?.csrf, auditQuery: { offset?: number; provider?: string; outcome?: string; clientId?: string; from?: string; to?: string } = {}) => {
    if (!csrf) return;
    try {
      const from = auditQuery.from ?? auditFrom; const to = auditQuery.to ?? auditTo;
      const query = { offset: auditQuery.offset ?? auditOffset, limit: 50, ...(auditQuery.provider ?? auditProvider ? { provider: auditQuery.provider ?? auditProvider } : {}), ...(auditQuery.outcome ?? auditOutcome ? { outcome: auditQuery.outcome ?? auditOutcome } : {}), ...(auditQuery.clientId ?? auditClientId ? { clientId: auditQuery.clientId ?? auditClientId } : {}), ...(from ? { from: Date.parse(from) } : {}), ...(to ? { to: Date.parse(to) } : {}) };
      const [nextClients, nextOperations, nextAudit, nextSummary, nextDiagnostics] = await Promise.all([api<Client[]>(csrf, 'clients.list'), api<Operation[]>(csrf, 'operations.list'), api<Page<Audit>>(csrf, 'audit.query', query), api<AuditSummary>(csrf, 'audit.summary'), api<Diagnostics>(csrf, 'diagnostics.summary')]);
      setClients(nextClients); setOperations(nextOperations); setAudit(nextAudit.items); setAuditTotal(nextAudit.total); setAuditOffset(nextAudit.offset); setAuditSummary(nextSummary); setDiagnostics(nextDiagnostics); setError('');
    } catch (cause) { setError(cause instanceof Error ? cause.message : 'Could not refresh management data.'); }
  };
  useEffect(() => { void (async () => {
    try { const next = await (await fetch('/api/bootstrap', { credentials: 'same-origin' })).json() as Bootstrap; setBootstrap(next); await refresh(next.csrf); }
    catch { setError('Management session expired. Re-open the local management link.'); }
  })(); }, []);
  if (!bootstrap) return <main className="loading">Opening secure management session… {error && <p>{error}</p>}</main>;
  const saveClient = async (event: React.FormEvent) => {
    event.preventDefault(); setCreatedToken('');
    try {
      const ids = containerIds.split(/[\n,]/).map((value) => value.trim()).filter(Boolean);
      const expiry = Date.parse(expiresAt);
      if (!ids.length) throw new Error('Enter at least one approved container ID. Use doctor --containers <name> to discover an exact ID without reading item content.');
      if (!actions.length) throw new Error('Choose at least one action.');
      if (!Number.isFinite(expiry) || expiry <= Date.now()) throw new Error('Choose a future expiration time.');
      if (fields === 'busy' && (provider !== 'calendar' || actions.some((action) => action !== 'read'))) throw new Error('Busy projection is available only for Calendar read access.');
      const grant = { provider, containerIds: ids, actions, fields, approval, expiresAt: expiry };
      if (editingClient) {
        const grants = editingClient.grants.map((current, index) => index === editingGrantIndex ? grant : current);
        await api(bootstrap.csrf, 'clients.update', { id: editingClient.id, name, grants });
        setEditingClient(undefined); setName(''); setContainerIds(''); await refresh();
      } else {
        const created = await api<{ client: Client; token: string }>(bootstrap.csrf, 'clients.create', { name, grants: [grant] });
        setCreatedToken(created.token); setName(''); setContainerIds(''); await refresh();
      }
    } catch (cause) { setError(cause instanceof Error ? cause.message : 'Client creation failed.'); }
  };
  const revoke = async (id: string) => { try { await api(bootstrap.csrf, 'clients.revoke', { id }); await refresh(); } catch (cause) { setError(String(cause)); } };
  const edit = (client: Client) => {
    const grant = client.grants[0]!;
    setEditingClient(client); setEditingGrantIndex(0); setName(client.name); setProvider(grant.provider); setContainerIds(grant.containerIds.join('\n')); setActions(grant.actions); setFields(grant.fields); setApproval(grant.approval); setExpiresAt(new Date(grant.expiresAt).toISOString().slice(0, 16)); setCreatedToken(''); setError('');
  };
  const selectGrant = (index: number) => {
    const grant = editingClient?.grants[index]; if (!grant) return;
    setEditingGrantIndex(index); setProvider(grant.provider); setContainerIds(grant.containerIds.join('\n')); setActions(grant.actions); setFields(grant.fields); setApproval(grant.approval); setExpiresAt(new Date(grant.expiresAt).toISOString().slice(0, 16));
  };
  const rotate = async (id: string) => {
    if (!window.confirm('Rotate this client credential? The old token will stop working immediately.')) return;
    try { const result = await api<{ token: string }>(bootstrap.csrf, 'clients.rotate', { id }); setCreatedToken(result.token); await refresh(); }
    catch (cause) { setError(cause instanceof Error ? cause.message : String(cause)); }
  };
  const approve = async (id: string) => { try { await api(bootstrap.csrf, 'operations.approve', { id }); await refresh(); } catch (cause) { setError(String(cause)); } };
  const reject = async (id: string) => { if (!window.confirm('Reject this plan? It will be cancelled and cannot be committed.')) return; try { await api(bootstrap.csrf, 'operations.reject', { id }); await refresh(); } catch (cause) { setError(String(cause)); } };
  const showPreview = async (id: string) => { try { setPreview(await api<OperationPreview>(bootstrap.csrf, 'operations.preview', { id })); } catch (cause) { setError(cause instanceof Error ? cause.message : String(cause)); } };
  const exportAudit = () => {
    const blob = new Blob([JSON.stringify(audit, null, 2)], { type: 'application/json' }); const url = URL.createObjectURL(blob);
    const link = document.createElement('a'); link.href = url; link.download = `apple-connector-audit-${new Date().toISOString().slice(0, 10)}.json`; link.click(); URL.revokeObjectURL(url);
  };
  const clearAudit = async () => { if (!window.confirm('Clear all local audit records? This cannot be undone.')) return; try { await api(bootstrap.csrf, 'audit.clear'); await refresh(); } catch (cause) { setError(String(cause)); } };
  const findContainers = async () => { try { setContainerDiscovery(await api<ContainerDiscovery>(bootstrap.csrf, 'diagnostics.find_containers', { name: containerName })); } catch (cause) { setError(cause instanceof Error ? cause.message : String(cause)); } };
  const runProbe = async () => { try { setProbeResult(await api(bootstrap.csrf, 'diagnostics.probe')); } catch (cause) { setError(cause instanceof Error ? cause.message : String(cause)); } };
  const runReadSummary = async (event: React.FormEvent) => { event.preventDefault(); try { setDebugReadResult(await api(bootstrap.csrf, 'diagnostics.read_summary', { clientId: debugClientId, provider: debugProvider, containerId: debugContainerId, limit: 10 })); } catch (cause) { setError(cause instanceof Error ? cause.message : String(cause)); } };
  const loadOperations = async (query: { offset?: number; provider?: string; state?: string } = {}) => { try { const provider = query.provider ?? operationProvider; const state = query.state ?? operationState; const result = await api<OperationPage>(bootstrap.csrf, 'operations.query', { offset: query.offset ?? operationOffset, limit: 50, ...(provider ? { provider } : {}), ...(state ? { state } : {}) }); setOperationRows(result.items); setOperationTotal(result.total); setOperationOffset(result.offset); } catch (cause) { setError(cause instanceof Error ? cause.message : String(cause)); } };
  const loadReminderDiagnostics = async () => { try { setReminderDiagnostics(await api<ReminderDiagnostic[]>(bootstrap.csrf, 'diagnostics.reminders_m1.list')); } catch (cause) { setError(cause instanceof Error ? cause.message : String(cause)); } };
  const startReminderDiagnostic = async (event: React.FormEvent) => { event.preventDefault(); try { await api(bootstrap.csrf, 'diagnostics.reminders_m1.start', { containerId: diagnosticListId }); setDiagnosticListId(''); await loadReminderDiagnostics(); } catch (cause) { setError(cause instanceof Error ? cause.message : String(cause)); } };
  const recoverReminderDiagnostic = async (probeId: string) => { if (!window.confirm('Retry exact cleanup for this recorded probe? It will not replay the write.')) return; try { await api(bootstrap.csrf, 'diagnostics.reminders_m1.recover', { probeId }); await loadReminderDiagnostics(); } catch (cause) { setError(cause instanceof Error ? cause.message : String(cause)); } };
  return <main>
    <header><div><h1>Apple Connector</h1><p>本机 Apple App 调试</p></div><button onClick={() => void refresh()}>刷新</button></header>
    <nav>{([['apps', 'APPs'], ['audit', '审计']] as const).map(([key, label]) => <button className={page === key ? 'active' : ''} onClick={() => setPage(key)} key={key}>{label}</button>)}</nav>
    {error && <p className="error" role="alert">{error}</p>}
    {page === 'apps' && <WebApps csrf={bootstrap.csrf} report={setError} />}
    {page === 'audit' && <WebAuditPage csrf={bootstrap.csrf} report={setError} />}
    {page === 'connections' && <section><h2>Clients</h2><p>Each client receives a separate credential. Revoke immediately when access is no longer needed.</p>
      <table><thead><tr><th>Name</th><th>State</th><th>Policy</th><th>Action</th></tr></thead><tbody>{clients.map((client) => <tr key={client.id}><td><code>{client.name}</code><small>{client.id}</small></td><td>{client.revoked ? 'Revoked' : 'Active'}</td><td>v{client.policyVersion}</td><td>{!client.revoked && <><button onClick={() => edit(client)}>Edit access</button> <button onClick={() => void rotate(client.id)}>Rotate token</button> <button className="danger" onClick={() => void revoke(client.id)}>Revoke</button></>}</td></tr>)}</tbody></table>
      <h3>{editingClient ? `Edit access for ${editingClient.name}` : 'Pair a client'}</h3><form onSubmit={saveClient}><p>{editingClient ? 'Saving updates the selected grant, preserves every other grant, and cancels this client’s unexecuted plans.' : 'A client receives exactly the scope configured below.'}</p>{editingClient && editingClient.grants.length > 1 && <fieldset><legend>Grant to edit</legend>{editingClient.grants.map((grant, index) => <button type="button" className={editingGrantIndex === index ? 'active' : ''} key={`${grant.provider}-${index}`} onClick={() => selectGrant(index)}>Grant {index + 1}: {grant.provider}</button>)}</fieldset>}<label>Name<input required value={name} onChange={(event) => setName(event.target.value)} maxLength={120} /></label><label>Data source<select value={provider} onChange={(event) => { const next = event.target.value as typeof provider; setProvider(next); setActions(next === 'notes' ? ['read'] : actions); if (next !== 'calendar') setFields('full'); }}><option value="reminders">Reminders</option><option value="notes">Notes (read-only)</option><option value="calendar">Calendar</option></select></label><fieldset><legend>Find an exact test container (metadata only)</legend><label>Name<input value={containerName} onChange={(event) => setContainerName(event.target.value)} placeholder="Exact list or folder name" /></label><button type="button" disabled={!containerName.trim()} onClick={() => void findContainers()}>Find IDs</button>{containerDiscovery && <small>{[...containerDiscovery.reminderLists.map((item) => `Reminders: ${item.name} — ${item.id}`), ...containerDiscovery.noteFolders.map((item) => `Notes: ${item.name}${item.shared ? ' (shared; unavailable)' : ''} — ${item.id}`)].join('\n') || 'No exact matching Reminders list or Notes folder.'}</small>}</fieldset><label>Approved container IDs <small>One per line or comma-separated. Discovery returns metadata only and never opens items.</small><textarea required value={containerIds} onChange={(event) => setContainerIds(event.target.value)} rows={3} placeholder="Dedicated test list or folder ID" /></label><fieldset><legend>Allowed actions</legend>{(['read', 'create', 'update', 'complete'] as const).map((action) => <label key={action}><input disabled={provider === 'notes' && action !== 'read'} type="checkbox" checked={actions.includes(action)} onChange={(event) => setActions((current) => event.target.checked ? [...new Set([...current, action])] : current.filter((item) => item !== action))} />{action}</label>)}</fieldset><label>Fields<select value={fields} onChange={(event) => setFields(event.target.value as typeof fields)}><option value="full">Full fields</option><option value="busy" disabled={provider !== 'calendar' || actions.some((action) => action !== 'read')}>Calendar busy only</option></select></label><label>Approval<select value={approval} onChange={(event) => setApproval(event.target.value as typeof approval)}><option value="automatic">Automatic within this scope</option><option value="required">Require approval for writes</option></select></label><label>Expires<input type="datetime-local" required value={expiresAt} onChange={(event) => setExpiresAt(event.target.value)} /></label><button type="submit">{editingClient ? 'Save access' : 'Create client'}</button>{editingClient && <button type="button" onClick={() => { setEditingClient(undefined); setName(''); setContainerIds(''); }}>Cancel edit</button>}</form>
      {createdToken && <aside className="secret"><strong>Copy this new or rotated token now — it will not be shown again.</strong><code>{createdToken}</code><p>Use this client token, never the administrator credential, in your MCP client configuration:</p><pre><code>{mcpConfig}</code></pre><button onClick={() => void navigator.clipboard?.writeText(mcpConfig)}>Copy MCP configuration</button><small>The background service must remain running. If your MCP client does not inherit your PATH, replace <code>apple-connector</code> with its verified absolute executable path.</small></aside>}</section>}
    {page === 'sources' && <section><h2>System and connector capabilities</h2>{diagnostics && <article className="card"><h3>Runtime diagnostics</h3><p>Connector {diagnostics.version}; native protocol v{diagnostics.nativeProtocolVersion}; system permissions: {diagnostics.systemPermissions}.</p><p>SQLite pages: {diagnostics.storage.pageCount.toLocaleString()} total, {diagnostics.storage.freePages.toLocaleString()} free, {diagnostics.storage.pageSize.toLocaleString()} bytes each. Pending-state counts: {JSON.stringify(diagnostics.storage.operationsByState)}.</p><p>Recent metadata-only errors: {diagnostics.storage.recentErrors.length}.</p></article>}{bootstrap.capabilities.map((source) => <article className="card" key={source.provider}><h3>{source.provider} <span className={`status ${source.status}`}>{source.status}</span></h3><p>Backend: {source.backend}; advertised operations: {source.operations.length ? source.operations.join(', ') : 'none'}.</p><ul>{source.limitations.map((limit) => <li key={limit}>{limit}</li>)}</ul></article>)}</section>}
    {page === 'mcp' && <section><h2>Connect an MCP client</h2><p>Keep the local Apple Connector service running, then configure your MCP client to launch the stdio entry. The management URL is not an MCP endpoint.</p><ol><li>Create a scoped client on the Connections page.</li><li>Copy its token once when it is created or rotated.</li><li>Add the configuration below to your MCP client, replacing the placeholder token or executable path as needed.</li><li>From that external client, call <code>connector.capabilities</code> and one authorized read. The resulting operation/audit metadata will appear in this management console when applicable.</li></ol><pre><code>{createdToken ? mcpConfig : JSON.stringify({ mcpServers: { 'apple-connector': { command: 'apple-connector', args: ['mcp'], env: { APPLE_CONNECTOR_TOKEN: 'PASTE_CLIENT_TOKEN_HERE' } } } }, null, 2)}</code></pre><button onClick={() => void navigator.clipboard?.writeText(createdToken ? mcpConfig : JSON.stringify({ mcpServers: { 'apple-connector': { command: 'apple-connector', args: ['mcp'], env: { APPLE_CONNECTOR_TOKEN: 'PASTE_CLIENT_TOKEN_HERE' } } } }, null, 2))}>Copy configuration</button><p><small>Never use the administrator token here. If the target client has a different PATH, replace <code>apple-connector</code> with its verified absolute executable path. This page can validate connector configuration guidance, but cannot claim an external client connected until that client performs a request.</small></p></section>}
    {page === 'records' && <section><h2>Operations</h2><p><label>Provider <select value={operationProvider} onChange={(event) => { const provider = event.target.value; setOperationProvider(provider); void loadOperations({ provider, offset: 0 }); }}><option value="">All</option><option value="calendar">Calendar</option><option value="reminders">Reminders</option><option value="notes">Notes</option></select></label><label>State <select value={operationState} onChange={(event) => { const state = event.target.value; setOperationState(state); void loadOperations({ state, offset: 0 }); }}><option value="">All</option><option value="prepared">Awaiting approval</option><option value="approved">Approved</option><option value="executing">Executing</option><option value="succeeded">Succeeded</option><option value="failed">Failed</option><option value="cancelled">Cancelled</option><option value="expired">Expired</option><option value="outcome_unknown">Outcome unknown</option></select></label></p><p><button disabled={operationOffset === 0} onClick={() => void loadOperations({ offset: Math.max(0, operationOffset - 50) })}>Previous</button> <button disabled={operationOffset + operationRows.length >= operationTotal} onClick={() => void loadOperations({ offset: operationOffset + 50 })}>Next</button> Showing {operationTotal ? operationOffset + 1 : 0}–{operationOffset + operationRows.length} of {operationTotal} matching operations.</p><table><thead><tr><th>Provider</th><th>State</th><th>Created</th><th>Expires</th></tr></thead><tbody>{operationRows.map((item) => <tr key={item.id}><td>{item.provider}<small>{item.id}</small></td><td>{item.state}</td><td>{date(item.createdAt)}</td><td>{date(item.expiresAt)}</td></tr>)}</tbody></table><h2>Audit (metadata only)</h2><p>{auditSummary.count.toLocaleString()} records using {auditSummary.bytes.toLocaleString()} logical bytes. Export contains the {audit.length} records displayed under the active filters, not the full audit history; titles, note bodies and tokens are never retained.</p><p><label>Provider <select value={auditProvider} onChange={(event) => { const provider = event.target.value; setAuditProvider(provider); void refresh(bootstrap.csrf, { provider, outcome: auditOutcome, clientId: auditClientId, from: auditFrom, to: auditTo, offset: 0 }); }}><option value="">All</option><option value="calendar">Calendar</option><option value="reminders">Reminders</option><option value="notes">Notes</option></select></label><label>Outcome <select value={auditOutcome} onChange={(event) => { const outcome = event.target.value; setAuditOutcome(outcome); void refresh(bootstrap.csrf, { provider: auditProvider, outcome, clientId: auditClientId, from: auditFrom, to: auditTo, offset: 0 }); }}><option value="">All</option><option value="allowed">Allowed</option><option value="denied">Denied</option><option value="succeeded">Succeeded</option><option value="failed">Failed</option><option value="outcome_unknown">Outcome unknown</option></select></label><label>Client <select value={auditClientId} onChange={(event) => { const clientId = event.target.value; setAuditClientId(clientId); void refresh(bootstrap.csrf, { provider: auditProvider, outcome: auditOutcome, clientId, from: auditFrom, to: auditTo, offset: 0 }); }}><option value="">All</option>{clients.map((client) => <option key={client.id} value={client.id}>{client.name}</option>)}</select></label><label>From <input type="datetime-local" value={auditFrom} onChange={(event) => { const from = event.target.value; setAuditFrom(from); void refresh(bootstrap.csrf, { provider: auditProvider, outcome: auditOutcome, clientId: auditClientId, from, to: auditTo, offset: 0 }); }} /></label><label>To <input type="datetime-local" value={auditTo} onChange={(event) => { const to = event.target.value; setAuditTo(to); void refresh(bootstrap.csrf, { provider: auditProvider, outcome: auditOutcome, clientId: auditClientId, from: auditFrom, to, offset: 0 }); }} /></label></p><p><button onClick={exportAudit}>Export displayed audit JSON</button> <button disabled={auditOffset === 0} onClick={() => void refresh(bootstrap.csrf, { offset: Math.max(0, auditOffset - 50) })}>Previous</button> <button disabled={auditOffset + audit.length >= auditTotal} onClick={() => void refresh(bootstrap.csrf, { offset: auditOffset + 50 })}>Next</button> <button className="danger" onClick={() => void clearAudit()}>Clear audit</button></p><p>Showing {auditTotal ? auditOffset + 1 : 0}–{auditOffset + audit.length} of {auditTotal} matching records.</p><table><thead><tr><th>Time</th><th>Action</th><th>Result</th><th>Items</th></tr></thead><tbody>{audit.map((item, index) => <tr key={`${item.at}-${index}`}><td>{date(item.at)}</td><td>{item.provider ? `${item.provider}: ` : ''}{item.action}</td><td>{item.outcome}{item.errorCode ? ` (${item.errorCode})` : ''}</td><td>{item.count}</td></tr>)}</tbody></table></section>}
    {page === 'pending' && <section><h2>Awaiting approval</h2><p>Review the exact immutable plan before approval. Approving grants permission to commit it; rejecting cancels it before any native call.</p>{preview && <article className="card"><h3>Plan preview</h3><p>{preview.provider} · expires {date(preview.expiresAt)}</p><pre><code>{JSON.stringify(preview.change, null, 2)}</code></pre><button onClick={() => setPreview(undefined)}>Close preview</button></article>}<table><thead><tr><th>Provider</th><th>Plan</th><th>Expires</th><th>Action</th></tr></thead><tbody>{operations.filter((item) => item.state === 'prepared').map((item) => <tr key={item.id}><td>{item.provider}</td><td><code>{item.id}</code></td><td>{date(item.expiresAt)}</td><td><button onClick={() => void showPreview(item.id)}>Review</button> <button onClick={() => void approve(item.id)}>Approve</button> <button className="danger" onClick={() => void reject(item.id)}>Reject</button></td></tr>)}</tbody></table></section>}
    {page === 'diagnostics' && <section><h2>Basic bridge check</h2><p>This fixed EventKit probe checks bridge visibility and authorization status. It does not enumerate personal data, request permissions, or write.</p><button onClick={() => void runProbe()}>Run no-content probe</button>{probeResult && <pre><code>{JSON.stringify(probeResult, null, 2)}</code></pre>}<h2>Bounded read summary</h2><p>Use an active client and one of its authorized Reminders lists or Notes folders. The service reads at most 10 items to diagnose access, returns only a count, and never displays titles, snippets, bodies, IDs, or tokens.</p><form onSubmit={runReadSummary}><label>Client<select required value={debugClientId} onChange={(event) => setDebugClientId(event.target.value)}><option value="">Choose an active client</option>{clients.filter((client) => !client.revoked).map((client) => <option value={client.id} key={client.id}>{client.name}</option>)}</select></label><label>Provider<select value={debugProvider} onChange={(event) => setDebugProvider(event.target.value as typeof debugProvider)}><option value="reminders">Reminders</option><option value="notes">Notes</option></select></label><label>Authorized container ID<input required value={debugContainerId} onChange={(event) => setDebugContainerId(event.target.value)} /></label><button type="submit">Run read summary</button></form>{debugReadResult && <pre><code>{JSON.stringify(debugReadResult, null, 2)}</code></pre>}<h2>Reminders M1 diagnostic</h2><p>This explicit diagnostic writes only to the dedicated test list you select. It persists a UUID journal before mutation, never automatically replays writes, and attempts exact cleanup by retained ID.</p><form onSubmit={startReminderDiagnostic}><label>Dedicated Reminders list ID<input required value={diagnosticListId} onChange={(event) => setDiagnosticListId(event.target.value)} placeholder="Test list ID only" /></label><button type="submit">Run bounded diagnostic</button></form><p><button onClick={() => void loadReminderDiagnostics()}>Refresh diagnostic history</button></p>{reminderDiagnostics.map((item) => <article className="card" key={item.probeId}><h3>{item.active ? 'Running' : item.recoveryStatus} <small>{item.probeId}</small></h3><p>Test list: <code>{item.containerId}</code> · started {date(item.createdAt)}</p><p>{item.events.map((event) => `${event.stage}: ${event.status}${event.durationMs === undefined ? '' : ` (${event.durationMs}ms)`}`).join(' · ') || 'Journal created; awaiting first stage.'}</p>{!item.active && ['pending', 'outcome_unknown', 'ambiguous'].includes(item.recoveryStatus) && <button className="danger" onClick={() => void recoverReminderDiagnostic(item.probeId)}>Retry exact cleanup</button>}</article>)}</section>}
  </main>;
}

createRoot(document.getElementById('root')!).render(<StrictMode><App /></StrictMode>);
